(()=>{var a=class extends HTMLElement{constructor(){super(),this.layoutMasonry=this.layoutMasonry.bind(this)}connectedCallback(){requestAnimationFrame(()=>{this.layoutMasonry(),window.addEventListener("resize",this.debounceLayout.bind(this,100))})}disconnectedCallback(){window.removeEventListener("resize",this.debounceLayout)}debounceLayout(t){clearTimeout(this.timeoutId),this.timeoutId=setTimeout(this.layoutMasonry,t)}layoutMasonry(){let t=getComputedStyle(this).gridTemplateColumns.split(" ").length,o=Array.from(this.children);o.forEach((e,s)=>{if(e.style.marginTop="0px",s>=t){let i=o[s-t],n=i.offsetTop+i.offsetHeight+parseFloat(getComputedStyle(this).rowGap),r=e.offsetTop,l=n-r;e.style.marginTop=`${l}px`}})}};customElements.define("custom-masonry",a)})();
